UPDATE paiflow_run SET state=#{state},worker_id=#{workerId},lease_id=#{leaseId},attempt=#{attempt},
  lease_expires_at=#{leaseExpiresAt},execution_started_at=#{executionStartedAt},last_event_seq=#{lastEventSeq},result_json=#{resultJson},result_hash=#{resultHash},
  revision=revision+1,update_time=UTC_TIMESTAMP() WHERE id=#{id} AND revision=#{revision}
